def rewrite_query(
        query: str, 
        context: str, 
        knowledge_graph,
        rewrite_type: str,
        use_fast=False,
        logger=logger,
        bg_prompt:str='',
    ) -> List[Dict[str, int]]:
    query = synonym_replacement(query)
    faculty = info_extractor.extract_faculty(context)
    context = f"{context}\nCONTEXT中涉及专业/学院：{faculty}" if faculty else context
    # 根据rewrite_type 选择不同的提示模板
    if rewrite_type == 'policy':
        if use_fast:
            prompt = QUERY_REWRITE_PROMPT_MAPPING['policy_fast'].replace('$query$', query).replace('$context$', context).replace('$category$', knowledge_graph)
            logger.info("【POLICY】CONTEXT✅；CATEGORY✅；FAST✅；")
        else:
            if context and knowledge_graph:
                prompt = QUERY_REWRITE_PROMPT_MAPPING['school_policy']['with_context_category'].replace('$query$', query).replace('$context$', context).replace('$category$', knowledge_graph)
                logger.info("【POLICY】CONTEXT✅；CATEGORY✅；FAST❌；")
            elif context:
                prompt = QUERY_REWRITE_PROMPT_MAPPING['school_policy']['with_context'].replace('$query$', query).replace('$context$', context).replace('$category$', knowledge_graph)
                logger.info("【POLICY】CONTEXT✅；CATEGORY❌；FAST❌；")
            elif knowledge_graph:
                prompt = QUERY_REWRITE_PROMPT_MAPPING['school_policy']['with_category'].replace('$query$', query).replace('$category$', knowledge_graph)
                logger.info("【POLICY】CONTEXT❌；CATEGORY✅；FAST❌；")
            else:
                prompt = QUERY_REWRITE_PROMPT_MAPPING['school_policy']['only_query'].replace('$query$', query).replace('$category$', knowledge_graph)
                logger.info("【POLICY】CONTEXT❌；CATEGORY❌；FAST❌；")
    elif rewrite_type == 'knowledge':   
        if use_fast:
            prompt = QUERY_REWRITE_PROMPT_MAPPING['knowledge_fast'].replace('$query$', query).replace('$context$', context)
            logger.info("【KNOWLEDGE】CONTEXT✅；CATEGORY✅；FAST✅；")
        else:
            prompt = QUERY_REWRITE_PROMPT_MAPPING['knowledge'].replace('$query$', query).replace('$context$', context)
            logger.info("【KNOWLEDGE】CONTEXT✅；CATEGORY❌；FAST❌；")
    else:
        if use_fast:
            prompt = QUERY_REWRITE_PROMPT_MAPPING['general_fast'].replace('$query$', query).replace('$context$', context)
            logger.info("【GENERAL】CONTEXT✅；CATEGORY❌；FAST✅；")
        else:
            prompt = QUERY_REWRITE_PROMPT_MAPPING['general'].replace('$query$', query).replace('$context$', context)
            logger.info("【GENERAL】CONTEXT✅；CATEGORY❌；FAST❌；")
    # 调用 GPT 服务生成响应
    response = gpt_service.gpt_response(prompt, bg_prompt=bg_prompt)
    logger.info(f"【REWRITE】QUERY: {query}；CONTEXT: {context}；KNOWLEDGE_GRAPH: {knowledge_graph}；")
    return process_response(response, query)


def process_response(response: str, query: str) -> List[Dict[str, int]]:
    if response:
        query_json = text_extraction.extract_json_from_text(response)
        if query_json and isinstance(query_json, dict):
            # 提取 JSON 的键并获取查询列表
            key = list(query_json.keys())[0]
            query_list = query_json.get(key, [query])
            if isinstance(query_list, str):
                query_list = [query_list]
            # 按查询长度降序排序，只保留前三个
            query_list.sort(key=lambda x: len(x), reverse=True)
            query_list = query_list[:3]
            if query_list:
                # 返回格式化的查询列表
                return response, [{'text': query, 'type': i + 1} for i, query in enumerate(query_list)]
    # 如果没有响应，返回默认的原始查询
    return response, [{'text': query, 'type': 1}]
